    }
  }

  History.init({
    id: {
      type: DataTypes.INTEGER,
      autoIncrement: true,
      primaryKey: true
    },
    patientId: {
      type: DataTypes.INTEGER,
      allowNull: false
    },
    doctorId: {
      type: DataTypes.INTEGER,
      allowNull: false
    },
    description: {
      type: DataTypes.TEXT,
      allowNull: true
    },
    files: {
      type: DataTypes.STRING,  // Nếu lưu file path hoặc image URL
      allowNull: true
    }
  }, {
    sequelize,
    modelName: 'History',
    tableName: 'Histories',  // hoặc 'History' nếu bạn muốn giữ nguyên tên
    timestamps: true
  });

  return History;
};

